func checkJSComponents(t *testing.T, got []Component, want map[string][2]bool) {
	t.Helper()
	m := byName(got)
	if len(m) != len(want) {
		t.Errorf("want %d components, got %d: %v", len(want), len(m), m)
	}
	for key, flags := range want {
		c, ok := m[key]
		if !ok {
			t.Errorf("%s missing", key)
			continue
		}
		if c.Direct != flags[0] || c.Dev != flags[1] || c.Ecosystem != EcosystemNpm {
			t.Errorf("%s: direct=%v dev=%v eco=%s, want direct=%v dev=%v", key, c.Direct, c.Dev, c.Ecosystem, flags[0], flags[1])
		}
	}
}

func TestYarnLockParser(t *testing.T) {
	for name, lock := range map[string]string{"classic": yarnClassic, "berry": yarnBerry} {
		t.Run(name, func(t *testing.T) {
			root := writeFiles(t, map[string]string{"package.json": pkgJSONForLocks, "yarn.lock": lock})
			res, err := YarnLockParser{}.Parse(filepath.Join(root, "yarn.lock"), "yarn.lock")
			if err != nil {
				t.Fatal(err)
			}
			want := map[string][2]bool{ // {direct, dev}
				"@babel/code-frame@7.0.0": {true, true},
				"lodash@4.17.15":          {true, false},
				"minimist@0.0.8":          {false, false},
			}
			if name == "classic" {
				want["chalk@2.4.2"] = [2]bool{false, false}
				want["mkdirp@0.5.1"] = [2]bool{true, false}
			}
			checkJSComponents(t, res.Components, want)
		})
	}
}

func TestYarnEntryName(t *testing.T) {
	cases := map[string]string{
		`"@babel/core@^7.0.0", "@babel/core@^7.1.0"`: "@babel/core",
		`chalk@^2.0.0, chalk@^2.4.2`:                 "chalk",
		`"lodash@npm:^4.17.15"`:                      "lodash",
		`__metadata`:                                 "",
		`"web@workspace:."`:                          "",
		`"x@link:../x"`:                              "",
		`"fsevents@patch:fsevents@npm%3A2.3.3#x"`:    "",
		`"@scope"`:                                   "",
	}
	for key, want := range cases {
		if got := yarnEntryName(key); got != want {
			t.Errorf("yarnEntryName(%s) = %q want %q", key, got, want)
		}
	}
}

