func TestPnpmLockParser(t *testing.T) {
	for name, lock := range map[string]string{"v9": pnpmV9, "v6": pnpmV6, "v5": pnpmV5} {
		t.Run(name, func(t *testing.T) {
			root := writeFiles(t, map[string]string{"pnpm-lock.yaml": lock})
			res, err := PnpmLockParser{}.Parse(filepath.Join(root, "pnpm-lock.yaml"), "pnpm-lock.yaml")
			if err != nil {
				t.Fatal(err)
			}
			checkJSComponents(t, res.Components, map[string][2]bool{
				"@babel/code-frame@7.0.0": {true, true},
				"lodash@4.17.15":          {true, false},
				"minimist@0.0.8":          {false, false},
				// direct only via the packages/app importer in v9
				"react-dom@18.2.0": {name == "v9", false},
			})
		})
	}
}

func TestPnpmLockParser_InvalidYAML(t *testing.T) {
	root := writeFiles(t, map[string]string{"pnpm-lock.yaml": "packages: [unclosed"})
	if _, err := (PnpmLockParser{}).Parse(filepath.Join(root, "pnpm-lock.yaml"), "pnpm-lock.yaml"); err == nil {
		t.Fatal("expected error")
	}
}

func TestPnpmPackageKey(t *testing.T) {
	cases := []struct{ key, name, version string }{
		{"lodash@4.17.15", "lodash", "4.17.15"},
		{"@babel/code-frame@7.0.0", "@babel/code-frame", "7.0.0"},
		{"/lodash@4.17.15", "lodash", "4.17.15"},
		{"/react-dom@18.2.0(react@18.2.0)", "react-dom", "18.2.0"},
		{"/@scope/pkg@1.0.0(peer@2.0.0)", "@scope/pkg", "1.0.0"},
		{"/lodash/4.17.15", "lodash", "4.17.15"},
		{"/@babel/code-frame/7.0.0", "@babel/code-frame", "7.0.0"},
		{"/react-dom/18.2.0_react@18.2.0", "react-dom", "18.2.0"},
		{"/@scope/pkg/1.0.0_react@18.2.0", "@scope/pkg", "1.0.0"},
		{"github.com/user/repo/abc123", "", ""},
		{"file:../local", "", ""},
		{"@scope", "", ""},
	}
	for _, c := range cases {
		n, v, ok := pnpmPackageKey(c.key)
		if n != c.name || v != c.version || ok != (c.name != "") {
			t.Errorf("pnpmPackageKey(%q) = (%q,%q,%v) want (%q,%q)", c.key, n, v, ok, c.name, c.version)
		}
	}
}

func TestNpmManifestCheck_AcceptsAnyJSLock(t *testing.T) {
	for _, lock := range JSLockFiles {
		root := writeFiles(t, map[string]string{"package.json": "{}", lock: ""})
		res, _ := NpmManifestCheck{}.Parse(filepath.Join(root, "package.json"), "package.json")
		if len(res.Warnings) != 0 {
			t.Errorf("%s present but warned: %v", lock, res.Warnings)
		}
	}
}
